SET escape = off;
CREATE TABLE public.wms_inbound_order_item (
    id character varying(128 char) NOT NULL,
    tenant_id character varying(128 char),
    inbound_order_id character varying(128 char) DEFAULT NULL::varchar,
    batch_code character varying(255 char) DEFAULT NULL::varchar,
    material_code character varying(255 char) DEFAULT NULL::varchar,
    reason character varying(255 char) DEFAULT NULL::varchar,
    owner_project character varying(255 char) DEFAULT NULL::varchar,
    supplier_code character varying(255 char) DEFAULT NULL::varchar,
    purchase_order_code character varying(255 char) DEFAULT NULL::varchar,
    purchase_order_line_number character varying(255 char) DEFAULT NULL::varchar,
    purchase_brand character varying(255 char) DEFAULT NULL::varchar,
    arrival_brand character varying(255 char) DEFAULT NULL::varchar,
    purchase_spec character varying(255 char) DEFAULT NULL::varchar,
    arrival_spec character varying(255 char) DEFAULT NULL::varchar,
    purchase_quantity numeric(22,10) DEFAULT 0,
    arrival_quantity numeric(22,10) DEFAULT 0,
    unit_price numeric(22,10) DEFAULT 0,
    total_price numeric(22,10) DEFAULT 0,
    recycle_order_code character varying(255 char) DEFAULT NULL::varchar,
    recycle_order_item_id character varying(128 char) DEFAULT NULL::varchar,
    received_quantity numeric(22,10) DEFAULT 0,
    location_ids jsonb,
    status smallint DEFAULT 0,
    package_intact smallint DEFAULT 0,
    material_intact smallint DEFAULT 0,
    meets_purchase_requirements smallint DEFAULT 0,
    document_reviewed_status smallint DEFAULT 0,
    document_reviewed_remark character varying(255 char) DEFAULT NULL::varchar,
    demand_dept_quality_inspection_status smallint DEFAULT 0,
    demand_dept_unqualified_unit_quantity numeric(22,10) DEFAULT 0,
    technical_dept_quality_inspection_status smallint DEFAULT 0,
    technical_dept_unqualified_unit_quantity numeric(22,10) DEFAULT 0,
    demand_dept character varying(255 char) DEFAULT NULL::varchar,
    demand_reporter character varying(255 char) DEFAULT NULL::varchar,
    delivery_department character varying(255 char) DEFAULT NULL::varchar,
    delivery_person character varying(255 char) DEFAULT NULL::varchar,
    warehouse_keeper_id character varying(128 char) DEFAULT NULL::varchar,
    document_reviewer_id character varying(128 char) DEFAULT NULL::varchar,
    ext_attribute jsonb,
    ext_string1 character varying(255 char) DEFAULT NULL::varchar,
    ext_string2 character varying(255 char) DEFAULT NULL::varchar,
    ext_string3 character varying(255 char) DEFAULT NULL::varchar,
    ext_string4 character varying(255 char) DEFAULT NULL::varchar,
    ext_string5 character varying(255 char) DEFAULT NULL::varchar,
    ext_integer1 integer DEFAULT 0,
    ext_integer2 integer DEFAULT 0,
    ext_integer3 integer DEFAULT 0,
    ext_number1 numeric(10,2) DEFAULT 0,
    ext_number2 numeric(10,2) DEFAULT 0,
    ext_number3 numeric(10,2) DEFAULT 0,
    ext_json1 jsonb,
    ext_json2 jsonb,
    remarks clob,
    create_by character varying(128 char) DEFAULT NULL::varchar,
    create_by_name character varying(50 char) DEFAULT NULL::varchar,
    create_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    update_by character varying(128 char) DEFAULT NULL::varchar,
    update_by_name character varying(50 char) DEFAULT NULL::varchar,
    update_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    del_flag character(1 char) DEFAULT '0'::bpchar,
    recommended_location_id character varying(128 char),
    return_status smallint,
    reversed_quantity numeric(22,10) DEFAULT 0
);


