    material_name character varying(255 char) DEFAULT NULL::varchar,
    material_group_code character varying(255 char) DEFAULT NULL::varchar,
    material_group_name character varying(255 char) DEFAULT NULL::varchar,
    spare_part_model character varying(255 char) DEFAULT NULL::varchar,
    spare_part_model_name character varying(255 char) DEFAULT NULL::varchar,
    factory_code character varying(255 char) DEFAULT NULL::varchar,
    factory_name character varying(255 char) DEFAULT NULL::varchar,
    purchase_strategy character varying(255 char) DEFAULT NULL::varchar,
    purchase_strategy_name character varying(255 char) DEFAULT NULL::varchar,
    delete_flag character varying(255 char) DEFAULT NULL::varchar,
    item_category character varying(255 char) DEFAULT NULL::varchar,
    account_assign_category character varying(255 char) DEFAULT NULL::varchar,
    order_quantity numeric(22,10) DEFAULT 0,
    unit character varying(255 char) DEFAULT NULL::varchar,
    price numeric(22,10) DEFAULT 0,
    currency character varying(255 char) DEFAULT NULL::varchar,
    price_unit character varying(255 char) DEFAULT NULL::varchar,
    delivery_completed smallint DEFAULT 0,
    undelivered_quantity numeric(22,10) DEFAULT 0,
    received_quantity numeric(22,10) DEFAULT 0,
    received_amount numeric(22,10) DEFAULT 0,
    estimated_quantity numeric(22,10) DEFAULT 0,
    estimated_amount numeric(22,10) DEFAULT 0,
    order_delivery_date date,
    receipt_date date,
    invoiced_quantity numeric(22,10) DEFAULT 0,
    invoiced_amount numeric(22,10) DEFAULT 0,
    invoice_date date,
    project_code character varying(255 char) DEFAULT NULL::varchar,
    pr_create_date date,
    pr_code character varying(255 char) DEFAULT NULL::varchar,
    pr_line_number character varying(255 char) DEFAULT NULL::varchar,
    tax_code character varying(255 char) DEFAULT NULL::varchar,
    net_amount numeric(22,10) DEFAULT 0,
    total_amount numeric(22,10) DEFAULT 0,
    gh_storage_block character varying(255 char) DEFAULT NULL::varchar,
    gh_storage_block_name character varying(255 char) DEFAULT NULL::varchar,
    gh_storage_level character varying(255 char) DEFAULT NULL::varchar,
    gh_storage_level_name character varying(255 char) DEFAULT NULL::varchar,
    purchase_business_type character varying(255 char) DEFAULT NULL::varchar,
    company_code character varying(255 char) DEFAULT NULL::varchar,
    company_name character varying(255 char) DEFAULT NULL::varchar,
    department_code character varying(255 char) DEFAULT NULL::varchar,
    requirement_plan_code character varying(255 char) DEFAULT NULL::varchar,
    requirement_plan_line_number character varying(255 char) DEFAULT NULL::varchar,
    submit_date date,
    plan_category character varying(255 char) DEFAULT NULL::varchar,
    plan_category_name character varying(255 char) DEFAULT NULL::varchar,
    material_main_category_name character varying(255 char) DEFAULT NULL::varchar,
    material_sub_category_name character varying(255 char) DEFAULT NULL::varchar,
    document_type_name character varying(255 char) DEFAULT NULL::varchar,
    undelivered_amount numeric(22,10) DEFAULT 0,
    uninvoiced_amount numeric(22,10) DEFAULT 0,
    uninvoiced_quantity numeric(22,10) DEFAULT 0,
    original_supplier_code character varying(255 char) DEFAULT NULL::varchar,
    original_supplier_name character varying(255 char) DEFAULT NULL::varchar,
    legal_contract_code character varying(255 char) DEFAULT NULL::varchar,
    usage_direction character varying(255 char) DEFAULT NULL::varchar,
    usage_direction_name character varying(255 char) DEFAULT NULL::varchar,
    budget_category character varying(255 char) DEFAULT NULL::varchar,
    budget_category_name character varying(255 char) DEFAULT NULL::varchar,
    payment_terms character varying(255 char) DEFAULT NULL::varchar,
    remarks clob,
    create_by character varying(128 char) DEFAULT NULL::varchar,
    create_by_name character varying(50 char) DEFAULT NULL::varchar,
    create_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    update_by character varying(128 char) DEFAULT NULL::varchar,
    update_by_name character varying(50 char) DEFAULT NULL::varchar,
    update_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    del_flag character(1 char) DEFAULT '0'::bpchar
);


