--

SET escape = off;
CREATE TABLE public.wms_purchase_order_item (
    id character varying(128 char) NOT NULL,
    tenant_id character varying(128 char),
    purchase_order_id character varying(128 char) DEFAULT NULL::varchar,
    purchase_order_code character varying(255 char) DEFAULT NULL::varchar,
    order_date date,
    supplier_code character varying(255 char) DEFAULT NULL::varchar,
    internal_contract_code character varying(255 char) DEFAULT NULL::varchar,
    internal_contract_name character varying(255 char) DEFAULT NULL::varchar,
    srm_contract_code character varying(255 char) DEFAULT NULL::varchar,
    line_number character varying(255 char) DEFAULT NULL::varchar,
    material_code character varying(255 char) DEFAULT NULL::varchar,
    material_name character varying(255 char) DEFAULT NULL::varchar,
    material_group_code character varying(255 char) DEFAULT NULL::varchar,
    spare_part_model character varying(255 char) DEFAULT NULL::varchar,
    spare_part_model_name character varying(255 char) DEFAULT NULL::varchar,
    factory_code character varying(255 char) DEFAULT NULL::varchar,
    item_category character varying(255 char) DEFAULT NULL::varchar,
    account_assign_category character varying(255 char) DEFAULT NULL::varchar,
    order_quantity numeric(22,10) DEFAULT 0,
    unit character varying(255 char) DEFAULT NULL::varchar,
    price numeric(22,10) DEFAULT 0,
    currency character varying(255 char) DEFAULT NULL::varchar,
    price_unit character varying(255 char) DEFAULT NULL::varchar,
    project_code character varying(255 char) DEFAULT NULL::varchar,
    ext_attribute jsonb,
    ext_string1 character varying(255 char) DEFAULT NULL::varchar,
    ext_string2 character varying(255 char) DEFAULT NULL::varchar,
    ext_string3 character varying(255 char) DEFAULT NULL::varchar,
    ext_string4 character varying(255 char) DEFAULT NULL::varchar,
    ext_string5 character varying(255 char) DEFAULT NULL::varchar,
    ext_integer1 integer DEFAULT 0,
    ext_integer2 integer DEFAULT 0,
    ext_integer3 integer DEFAULT 0,
    ext_number1 numeric(10,2) DEFAULT 0,
    ext_number2 numeric(10,2) DEFAULT 0,
    ext_number3 numeric(10,2) DEFAULT 0,
    ext_json1 jsonb,
    ext_json2 jsonb,
    remarks clob,
    create_by character varying(128 char) DEFAULT NULL::varchar,
    create_by_name character varying(50 char) DEFAULT NULL::varchar,
    create_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    update_by character varying(128 char) DEFAULT NULL::varchar,
    update_by_name character varying(50 char) DEFAULT NULL::varchar,
    update_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    del_flag character(1 char) DEFAULT '0'::bpchar,
    requirement_plan_code character varying(255 char) DEFAULT NULL::varchar,
    requirement_plan_line_number character varying(255 char) DEFAULT NULL::varchar,
    inbound_quantity numeric(22,10) DEFAULT 0,
    department_code character varying(100 char) DEFAULT NULL::varchar,
    department_name character varying(200 char) DEFAULT NULL::varchar,
    demand_reporter character varying(200 char) DEFAULT NULL::varchar
);


