CREATE TABLE public.wms_requisition_order_item (
    id character varying(128 char) NOT NULL,
    tenant_id character varying(128 char),
    requisition_order_id character varying(128 char) DEFAULT NULL::varchar,
    requisition_order_code character varying(255 char) DEFAULT NULL::varchar,
    material_code character varying(255 char) DEFAULT NULL::varchar,
    request_quantity numeric(22,10) DEFAULT 0,
    picked_quantity numeric(22,10) DEFAULT 0,
    ext_attribute jsonb,
    ext_string1 character varying(255 char) DEFAULT NULL::varchar,
    ext_string2 character varying(255 char) DEFAULT NULL::varchar,
    ext_string3 character varying(255 char) DEFAULT NULL::varchar,
    ext_string4 character varying(255 char) DEFAULT NULL::varchar,
    ext_string5 character varying(255 char) DEFAULT NULL::varchar,
    ext_integer1 integer DEFAULT 0,
    ext_integer2 integer DEFAULT 0,
    ext_integer3 integer DEFAULT 0,
    ext_number1 numeric(10,2) DEFAULT 0,
    ext_number2 numeric(10,2) DEFAULT 0,
    ext_number3 numeric(10,2) DEFAULT 0,
    ext_json1 jsonb,
    ext_json2 jsonb,
    remarks clob,
    create_by character varying(128 char) DEFAULT NULL::varchar,
    create_by_name character varying(50 char) DEFAULT NULL::varchar,
    create_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    update_by character varying(128 char) DEFAULT NULL::varchar,
    update_by_name character varying(50 char) DEFAULT NULL::varchar,
    update_date timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    del_flag character(1 char) DEFAULT '0'::bpchar,
    owner_project_type character varying(128 char),
    owner_project_code character varying(128 char),
    line_number character varying(255 char) DEFAULT NULL::varchar,
    requirement_date date,
    outbound_date date,
    requirement_plan_code character varying(255 char) DEFAULT NULL::varchar,
    status smallint DEFAULT 10,
    work_order_code character varying(128 char) DEFAULT NULL::varchar,
    material_document character varying(255 char) DEFAULT NULL::varchar
);


